def translate(label, lang='zh'):
    if label in TEXT:
        return TEXT[label][0 if lang == 'zh' else 1]
    parts = label.split(' / ', 1)
    if len(parts) == 2:
        first, second = parts
        a = bool(re.search(r'[㐀-鿿]', first))
        b = bool(re.search(r'[㐀-鿿]', second))
        if a != b:
            return first if (a and lang == 'zh') or (b and lang == 'en') else second
    return label
